using ZwSoft.ZwCAD.DatabaseServices;using ZwSoft.ZwCAD.Geometry;using System;using System.Collections.Generic;using System.Linq;
namespace Tgirrr.CadLisp { internal static class DripLayoutService {internal static Vector2d Direction(Polyline p){double best=-1;Vector2d dir=Vector2d.XAxis;for(int i=0;i<p.NumberOfVertices;i++){if(p.GetSegmentType(i)!=SegmentType.Line)continue;var seg=p.GetLineSegment2dAt(i);if(seg.Length>best){best=seg.Length;dir=seg.Direction;}}return dir.GetNormal();}internal static DBObjectCollection Inner(Polyline p,double inset){if(inset==0){var c=new DBObjectCollection();c.Add(p.Clone() as Polyline);return c;}DBObjectCollection a=null,b=null;try{a=p.GetOffsetCurves(inset);}catch{}try{b=p.GetOffsetCurves(-inset);}catch{}var candidates=new List<Polyline>();if(a!=null)candidates.AddRange(a.Cast<DBObject>().OfType<Polyline>());if(b!=null)candidates.AddRange(b.Cast<DBObject>().OfType<Polyline>());double sourceArea=Math.Abs(p.Area);double tolerance=Math.Max(sourceArea*1e-9,1e-9);var inside=candidates.Where(x=>{try{return x.Closed&&Math.Abs(x.Area)<sourceArea-tolerance;}catch{return false;}}).OrderByDescending(x=>Math.Abs(x.Area)).ToList();var result=new DBObjectCollection();foreach(var x in inside)result.Add(x);foreach(var x in candidates.Except(inside))x.Dispose();return result;}internal static bool PointInside(Polyline p,Point2d point){var far=new LineSegment2d(point,new Point2d(p.GeometricExtents.MaxPoint.X+(p.GeometricExtents.MaxPoint-p.GeometricExtents.MinPoint).Length+1,point.Y+0.1234567));int hits=0;for(int i=0;i<p.NumberOfVertices;i++){if(p.GetSegmentType(i)==SegmentType.Line){var pts=p.GetLineSegment2dAt(i).IntersectWith(far);hits+=pts?.Length??0;}else if(p.GetSegmentType(i)==SegmentType.Arc){var pts=p.GetArcSegment2dAt(i).IntersectWith(far);hits+=pts?.Length??0;}}return hits%2==1;}internal static List<Polyline> CurvedFill(Polyline boundary,double spacing){var result=new List<Polyline>();var seed=LongestArcChain(boundary);if(seed==null)return result;int misses=0;for(int signIndex=0;signIndex<2&&result.Count==0;signIndex++){double sign=signIndex==0?1:-1;misses=0;for(int n=1;n<10000&&misses<3;n++){DBObjectCollection offsets;try{offsets=seed.GetOffsetCurves(sign*n*spacing);}catch{break;}bool valid=false;foreach(Polyline curve in offsets.Cast<DBObject>().OfType<Polyline>()){var fitted=ExtendToBoundary(curve,boundary);curve.Dispose();if(fitted!=null){result.Add(fitted);valid=true;}}misses=valid?0:misses+1;}}seed.Dispose();return result;}internal sealed class ArcRun{internal readonly List<int> Segments=new List<int>();internal double Length,WeightedRadius,Turn,RadiusVariation;internal double Score=>Length*(1.0+Math.Min(WeightedRadius/Math.Max(Length,1e-9),3.0))/(1.0+RadiusVariation*2.0+Math.Max(0,Turn-Math.PI*0.85)*2.0);}
internal static Polyline LongestArcChain(Polyline boundary){int count=boundary.NumberOfVertices;var runs=new List<ArcRun>();for(int seed=0;seed<count;seed++){if(boundary.GetSegmentType(seed)!=SegmentType.Arc)continue;var run=new ArcRun();double firstRadius=0,lastRadius=0,lastSign=0;for(int k=0;k<count;k++){int i=(seed+k)%count;if(boundary.GetSegmentType(i)!=SegmentType.Arc)break;var arc=boundary.GetArcSegment2dAt(i);double bulge=boundary.GetBulgeAt(i),sign=Math.Sign(bulge),radius=arc.Radius,turn=Math.Abs(arc.EndAngle-arc.StartAngle);if(turn>Math.PI*2)turn=Math.PI*2-turn;if(run.Segments.Count>0){double ratio=Math.Max(radius,lastRadius)/Math.Max(Math.Min(radius,lastRadius),1e-9);if(sign!=lastSign||ratio>1.8||run.Turn+turn>Math.PI*1.15)break;run.RadiusVariation+=Math.Abs(radius-lastRadius)/Math.Max(lastRadius,1e-9);}else firstRadius=radius;double length=radius*turn;run.Segments.Add(i);run.Length+=length;run.WeightedRadius+=radius*length;run.Turn+=turn;lastRadius=radius;lastSign=sign;}if(run.Segments.Count>0){run.WeightedRadius/=Math.Max(run.Length,1e-9);runs.Add(run);seed+=run.Segments.Count-1;}}var best=runs.OrderByDescending(r=>r.Score).FirstOrDefault();if(best==null)return null;var poly=new Polyline();for(int k=0;k<best.Segments.Count;k++){int i=best.Segments[k];poly.AddVertexAt(k,boundary.GetPoint2dAt(i),boundary.GetBulgeAt(i),0,0);}int last=(best.Segments[best.Segments.Count-1]+1)%count;poly.AddVertexAt(best.Segments.Count,boundary.GetPoint2dAt(last),0,0,0);return poly;}internal static Polyline ExtendToBoundary(Polyline curve,Polyline boundary){if(curve.NumberOfVertices<2)return null;double reach=(boundary.GeometricExtents.MaxPoint-boundary.GeometricExtents.MinPoint).Length*2;var start=curve.StartPoint;var end=curve.EndPoint;Vector3d startTan,endTan;try{startTan=curve.GetFirstDerivative(start).GetNormal();endTan=curve.GetFirstDerivative(end).GetNormal();}catch{return null;}var startProbe=new Line{StartPoint=start-startTan*reach,EndPoint=start+startTan*reach};var endProbe=new Line{StartPoint=end-endTan*reach,EndPoint=end+endTan*reach};var sPoints=new Point3dCollection();var ePoints=new Point3dCollection();boundary.IntersectWith(startProbe,Intersect.OnBothOperands,sPoints,IntPtr.Zero,IntPtr.Zero);boundary.IntersectWith(endProbe,Intersect.OnBothOperands,ePoints,IntPtr.Zero,IntPtr.Zero);startProbe.Dispose();endProbe.Dispose();var startCandidates=sPoints.Cast<Point3d>().Where(p=>p.DistanceTo(start)>1e-7).OrderBy(p=>(p-start).DotProduct(startTan)).ToList();var endCandidates=ePoints.Cast<Point3d>().Where(p=>p.DistanceTo(end)>1e-7).OrderByDescending(p=>(p-end).DotProduct(endTan)).ToList();if(startCandidates.Count==0||endCandidates.Count==0)return null;var newStart=startCandidates[0];var newEnd=endCandidates[0];var output=(Polyline)curve.Clone();output.SetPointAt(0,newStart.Convert2d(new Plane(new Point3d(0,0,0),new Vector3d(0,0,1))));output.SetPointAt(output.NumberOfVertices-1,newEnd.Convert2d(new Plane(new Point3d(0,0,0),new Vector3d(0,0,1))));Point3d mid;try{mid=output.GetPointAtDist(output.Length/2);}catch{output.Dispose();return null;}if(!PointInside(boundary,new Point2d(mid.X,mid.Y))){output.Dispose();return null;}return output;}internal static double GentleTurn(Polyline p){int n=p.NumberOfVertices;if(n<3)return 0;int flips=0;double lastSign=0;var prev=new Vector2d(1,0);bool hasPrev=false;for(int i=0;i<=n;i++){var a=p.GetPoint2dAt(i%n);var b=p.GetPoint2dAt((i+1)%n);var v=b-a;if(v.Length<1e-9)continue;v=v.GetNormal();if(hasPrev){double cross=prev.X*v.Y-prev.Y*v.X;double dot=prev.X*v.X+prev.Y*v.Y;double ang=Math.Atan2(cross,dot);if(Math.Abs(ang)>0.09){double sign=Math.Sign(ang);if(sign!=0){if(lastSign!=0&&sign!=lastSign)flips++;lastSign=sign;}}}prev=v;hasPrev=true;}return flips;}internal static bool ShouldCurveFollow(Polyline region,double spacing){if(region==null||spacing<=0)return false;if(GentleTurn(region)>=6)return true;double perimeter=0;try{perimeter=region.Length;}catch{return false;}if(perimeter<=0)return false;var chain=LongestArcChain(region);if(chain==null)return false;double chainLen=0;try{chainLen=chain.Length;}catch{}chain.Dispose();return chainLen>=Math.Max(4.0*spacing,0.3*perimeter);}internal static List<Polyline> ContourRings(Polyline region,double spacing){var result=new List<Polyline>();if(region==null||spacing<=0)return result;double baseArea=0;try{baseArea=Math.Abs(region.Area);}catch{return result;}if(baseArea<=0)return result;double sign=0;foreach(var s in new double[]{1,-1}){DBObjectCollection off=null;try{off=region.GetOffsetCurves(s*spacing);}catch{}if(off==null)continue;bool ok=false;foreach(Polyline c in off.Cast<DBObject>().OfType<Polyline>()){try{if(c.Closed&&Math.Abs(c.Area)<baseArea)ok=true;}catch{}}foreach(DBObject o in off)o.Dispose();if(ok){sign=s;break;}}if(sign==0)return result;double prevMax=baseArea;double minArea=spacing*spacing*0.25;for(int k=1;k<3000;k++){DBObjectCollection offsets;try{offsets=region.GetOffsetCurves(sign*k*spacing);}catch{break;}var frags=offsets.Cast<DBObject>().OfType<Polyline>().ToList();double maxArea=0;var keep=new List<Polyline>();foreach(var c in frags){bool good=false;try{if(c.Closed){var a=Math.Abs(c.Area);if(a>minArea&&a<prevMax){var mid=c.GetPointAtDist(c.Length/2);good=PointInside(region,new Point2d(mid.X,mid.Y));if(good&&a>maxArea)maxArea=a;}}}catch{}if(good)keep.Add(c);}foreach(var c in frags)if(!keep.Contains(c))c.Dispose();if(keep.Count==0)break;prevMax=maxArea;result.AddRange(keep);}return result;}internal static List<Polyline> CurvedFollow(Polyline seedArc,Polyline region,double spacing){if(seedArc==null)return ContourRings(region,spacing);var result=new List<Polyline>();bool ownSeed=false;if(seedArc==null||seedArc.NumberOfVertices<2||region==null||spacing<=0)return result;double sign=0;foreach(var s in new double[]{1,-1}){DBObjectCollection off=null;try{off=seedArc.GetOffsetCurves(s*spacing);}catch{}if(off==null)continue;foreach(Polyline c in off.Cast<DBObject>().OfType<Polyline>()){try{var mid=c.GetPointAtDist(c.Length/2);if(PointInside(region,new Point2d(mid.X,mid.Y))){sign=s;break;}}catch{}}foreach(DBObject o in off)o.Dispose();if(sign!=0)break;}if(sign==0)return result;int misses=0;for(int k=1;k<5000;){int budget=result.Count==0?500:3;if(misses>=budget)break;DBObjectCollection offsets;try{offsets=seedArc.GetOffsetCurves(sign*k*spacing);}catch{break;}bool valid=false;foreach(Polyline curve in offsets.Cast<DBObject>().OfType<Polyline>()){var fitted=ExtendToBoundary(curve,region);curve.Dispose();if(fitted!=null){result.Add(fitted);valid=true;}}misses=valid?0:misses+1;k++;}if(ownSeed)seedArc.Dispose();return result;}internal static List<Line> Fill(Polyline boundary,double spacing,Vector2d direction){return Fill(boundary,spacing,direction,null);}internal static List<Line> Fill(Polyline boundary,double spacing,Vector2d direction,double? rowOrigin){var polygon=Tessellate(boundary,spacing);return DripFillGeometry.Fill(polygon,spacing,new DripVector(direction.X,direction.Y),rowOrigin).Select(s=>new Line{StartPoint=new Point3d(s.Start.X,s.Start.Y,boundary.Elevation),EndPoint=new Point3d(s.End.X,s.End.Y,boundary.Elevation)}).ToList();}internal static Polyline SerpentinePath(List<Line> segments,Vector2d direction,double spacing,double elevation){if(segments==null||segments.Count<2)return null;var dsegs=segments.Select(l=>new DripSegment(new DripPoint(l.StartPoint.X,l.StartPoint.Y),new DripPoint(l.EndPoint.X,l.EndPoint.Y))).ToList();var path=DripFillGeometry.Serpentine(dsegs,new DripVector(direction.X,direction.Y),spacing);if(path.Count<2)return null;var poly=new Polyline();for(int i=0;i<path.Count;i++)poly.AddVertexAt(i,new Point2d(path[i].X,path[i].Y),0,0,0);poly.Closed=false;poly.Elevation=elevation;return poly;}internal static List<DripPoint> Tessellate(Polyline boundary,double spacing){int count=boundary.NumberOfVertices;bool hasArc=false;for(int i=0;i<count;i++)if(boundary.GetSegmentType(i)==SegmentType.Arc){hasArc=true;break;}var points=new List<DripPoint>();if(hasArc){try{double total=boundary.Length;double step=Math.Max(Math.Min(spacing/2.0,total/64.0),1e-9);int steps=(int)Math.Min(Math.Ceiling(total/step),20000);if(steps<16)steps=16;for(int k=0;k<steps;k++){var v=boundary.GetPointAtDist(total*k/steps);points.Add(new DripPoint(v.X,v.Y));}if(points.Count>=8)return points;}catch{}points.Clear();}for(int i=0;i<count;i++){var v=boundary.GetPoint2dAt(i);points.Add(new DripPoint(v.X,v.Y));}return points;}}
}
